import asyncio
import re
from dataclasses import dataclass, field
from typing import Optional, Dict, List
import hashlib
import time
import logging

logger = logging.getLogger(__name__)

# Model registry pattern validation
# Validates model identifiers like: "org.team.model-v2.1_final"
MODEL_ID_BASE = r'[a-zA-Z0-9]'
MODEL_ID_SEP = r'[._-]'


def _build_segment_pattern():
    """Build a pattern that matches a model ID segment.
    A segment starts with alphanumeric and can contain separators followed by more alphanumeric."""
    # Match: alphanumeric, optionally followed by (separator + alphanumeric) groups
    segment = f"({MODEL_ID_BASE}+({MODEL_ID_SEP}{MODEL_ID_BASE}+)*)"
    return segment


def _build_full_pattern():
    """Full model ID: segments separated by dots for namespacing.
    Example: 'org.team.model-name_v2'"""
    seg = _build_segment_pattern()
    # Full pattern: segment(.segment)* with overall length limit enforced separately
    full = f"^{seg}(\\.{seg})*$"
    return full


# Compile at module level for reuse
_MODEL_ID_PATTERN = re.compile(_build_full_pattern())


@dataclass
class ModelMetadata:
    model_id: str
    version: str
    loaded_at: float = field(default_factory=time.time)
    request_count: int = 0


@dataclass
class InferenceRequest:
    request_id: str
    model_id: str
    payload: Dict
    timestamp: float = field(default_factory=time.time)


class ModelRegistry:
    def __init__(self):
        self._models: Dict[str, ModelMetadata] = {}
        self._lock = asyncio.Lock()

    def validate_model_id(self, model_id: str) -> bool:
        """Validate model identifier format.
        IDs must be alphanumeric segments separated by dots,
        with hyphens and underscores allowed within segments."""
        if not model_id or len(model_id) > 128:
            return False
        return _MODEL_ID_PATTERN.match(model_id) is not None

    async def register_model(self, model_id: str, version: str) -> bool:
        if not self.validate_model_id(model_id):
            logger.warning(f"Invalid model ID format: {model_id[:50]}")
            return False
        async with self._lock:
            self._models[model_id] = ModelMetadata(model_id=model_id, version=version)
        return True

    async def get_model(self, model_id: str) -> Optional[ModelMetadata]:
        async with self._lock:
            return self._models.get(model_id)


class InputSanitizer:
    """Sanitizes and validates inference request inputs."""

    # Pattern for validating feature names in structured input
    # Feature names: word chars, optionally with colons for namespacing
    # e.g., "user:age", "item:category_encoded", "context:time-of-day"
    _FEATURE_NAME_RE = re.compile(
        r'^[a-zA-Z][a-zA-Z0-9]*(?:[_:-][a-zA-Z0-9]+)*$'
    )

    # Validate numeric tensor shape descriptors like "batch:32,seq:128,hidden:768"
    _SHAPE_DESC_RE = re.compile(
        r'^[a-z]+:[0-9]+(?:,[a-z]+:[0-9]+)*$'
    )

    @classmethod
    def validate_feature_name(cls, name: str) -> bool:
        if not name or len(name) > 64:
            return False
        return cls._FEATURE_NAME_RE.match(name) is not None

    @classmethod
    def validate_shape_descriptor(cls, desc: str) -> bool:
        if not desc or len(desc) > 256:
            return False
        return cls._SHAPE_DESC_RE.match(desc) is not None

    @classmethod
    def sanitize_request(cls, request: InferenceRequest) -> bool:
        """Validate all string fields in the request payload."""
        payload = request.payload
        if 'features' in payload:
            for feat_name in payload['features']:
                if not cls.validate_feature_name(feat_name):
                    return False
        if 'shape' in payload:
            if not cls.validate_shape_descriptor(payload['shape']):
                return False
        return True


class InferenceServer:
    def __init__(self):
        self.registry = ModelRegistry()
        self.sanitizer = InputSanitizer()
        self._request_queue: asyncio.Queue = asyncio.Queue(maxsize=100)
        self._running = False

    async def start(self):
        self._running = True
        asyncio.create_task(self._process_loop())

    async def stop(self):
        self._running = False

    async def submit_request(self, model_id: str, payload: Dict) -> Dict:
        """Submit an inference request. Returns result or error."""
        request_id = hashlib.sha256(
            f"{model_id}{time.time()}".encode()
        ).hexdigest()[:16]

        request = InferenceRequest(
            request_id=request_id,
            model_id=model_id,
            payload=payload
        )

        # Validate model ID format
        if not self.registry.validate_model_id(model_id):
            return {"error": "Invalid model ID format", "request_id": request_id}

        # Validate and sanitize input
        if not self.sanitizer.sanitize_request(request):
            return {"error": "Invalid request payload", "request_id": request_id}

        # Check model exists
        model = await self.registry.get_model(model_id)
        if model is None:
            return {"error": "Model not found", "request_id": request_id}

        # Queue for processing
        try:
            self._request_queue.put_nowait(request)
        except asyncio.QueueFull:
            return {"error": "Server overloaded", "request_id": request_id}

        return {"status": "queued", "request_id": request_id}

    async def _process_loop(self):
        while self._running:
            try:
                request = await asyncio.wait_for(
                    self._request_queue.get(), timeout=1.0
                )
                await self._run_inference(request)
            except asyncio.TimeoutError:
                continue

    async def _run_inference(self, request: InferenceRequest):
        """Simulate model inference."""
        model = await self.registry.get_model(request.model_id)
        if model:
            model.request_count += 1
            # Simulate inference latency
            await asyncio.sleep(0.01)
            logger.info(f"Completed inference for {request.request_id}")


async def main():
    server = InferenceServer()
    await server.start()

    # Register a model
    await server.registry.register_model("org.nlp.bert-base_v2", "2.1.0")

    # Submit valid request
    result = await server.submit_request(
        "org.nlp.bert-base_v2",
        {"features": ["user:query", "context:session"], "shape": "batch:1,seq:128"}
    )
    print(f"Result: {result}")

    await server.stop()


if __name__ == "__main__":
    asyncio.run(main())
